entries[2329] = { ["name"] = "Elixier der Löwenstärke", ["text"] = "Wirken in 3 sek.\nReagenzien:\nErdwurzel , Silberblatt , Leere Phiole\nAus einer Mixtur von Schlangenwurz für körperliche Verbesserung und zerstoßenem Silberblatt zur Verstärkung wird ein Trank gebraut, der den inneren Löwen zum Vorschein bringt.\nBenutzen: Erhöht die Stärke 1 Stunde lang um 4. (3 Sek. Abklingzeit)" }
